def render(number: int, lang: str) -> str:
    row = CONTENT[number][lang]
    title = next(item[f'title_{lang}'] for item in CURRICULUM['lessons'] if item['number'] == number)
    headings = HEAD[lang]
    shared = SCAFFOLD[lang]
    image = f'/static/course/informatics/{STEMS[number][1]}-{lang}.svg'
    sections = [
        ENRICHMENT[number][lang]['hook'] + f'\n\n![{title}]({image})',
        row['scene'] + '\n\n' + row['model'] + '\n\n' + ENRICHMENT[number][lang]['bridge'],
        row['boundary'],
        '`' + row['signal'] + '`',
        row['worked'],
        row['predict'] + '\n\n' + shared['predict'],
        row['fade'] + '\n\n' + shared['fade'],
        row['error'],
        row['transfer'],
        row['project'],
        row['task'] + ('\n\n' + CHECKPOINT[lang] if number == 18 else '') + '\n\n' + shared['task'],
        row['review'],
    ]
    lead_label = {'ru': 'Лид (summary)', 'kz': 'Лид (summary)', 'en': 'Lead (summary)'}[lang]
    body = f'# {title}\n\n_{lead_label}:_ **{row["lead"]}**\n\n'
    body += '\n\n'.join(f'## {heading}\n\n{section}' for heading, section in zip(headings, sections)) + '\n\n'
    if number < 18:
        next_title = next(item[f'title_{lang}'] for item in CURRICULUM['lessons'] if item['number'] == number + 1)
        next_slug = 'informatics-' + STEMS[number + 1][0]
        link_label = {'ru': 'Следующий урок', 'kz': 'Келесі сабақ', 'en': 'Next lesson'}[lang]
        body += f'[{link_label}: {next_title}](/read/{next_slug}?lang={lang})\n'
    else:
        link_label = {'ru': 'Следующий урок', 'kz': 'Келесі сабақ', 'en': 'Next lesson'}[lang]
        next_title = next(item[f'title_{lang}'] for item in CURRICULUM['lessons'] if item['number'] == 19)
        body += f'[{link_label}: {next_title}](/read/informatics-19-problem-decomposition?lang={lang})\n'
    return body

def main():
    for number, (stem, _) in STEMS.items():
        for lang in ('ru', 'kz', 'en'):
            suffix = '' if lang == 'ru' else f'-{lang}'
            (OUT / f'{stem}{suffix}.md').write_text(render(number, lang), encoding='utf-8')
    print('Generated 24 localized representation lessons')

if __name__ == '__main__':
    main()
